window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9eecb896f4ebe28c"]={"versions": [{"id": "FIG-9eecb896f4ebe28c", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR-Software-Component-Templates. Das Diagramm spezifiziert die Einbettung der ECU-Software-Komposition (<code>EcuSwComposition</code>) im Kontext der System- und ECU-Konfiguration (<code>EcuConfiguration</code>, <code>SystemTemplate::System</code>) sowie die Zuordnung von Service-Komponenten und Service-Konnektoren innerhalb eines Steuergeräte-Auszugs (ECU Extract).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell umfasst folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>EcuConfiguration</code> (<code>ARElement</code>): Referenziert über <code>+ecuExtract</code> genau ein <code>SystemTemplate::System</code> (Kardinalität <code>1</code>) und über <code>+ecuSwComposition</code> genau eine <code>Services::EcuSwComposition</code> (Kardinalität <code>1</code>).\n</li><li><code>SystemTemplate::System</code> (<code>ARElement</code>, Stereotyp «atpStructureElement»): Enthält per Komposition über die Rolle <code>+softwareComposition</code> genau ein <code>SystemTemplate::SoftwareComposition</code> (Kardinalität <code>1</code>).\n</li><li><code>Services::EcuSwComposition</code> (<code>ARElement</code>, Stereotyp «atpStructureElement»): Referenziert über <code>+ecuExtract</code> gerichtet genau ein <code>SystemTemplate::System</code> (Kardinalität <code>1</code>). Sie aggregiert per Komposition über <code>+component</code> beliebig viele Instanzen von <code>Services::ServiceComponentPrototype</code> (Kardinalität <code>*</code>) sowie über <code>+connector</code> beliebig viele Instanzen von <code>Composition::ServiceConnectorPrototype</code> (Kardinalität <code>*</code>).\n</li><li><code>SystemTemplate::SoftwareComposition</code> (<code>Identifiable</code>, Stereotyp «atpPrototype»): Typisiert über die Assoziation «isOfType» (<code>*</code> zu <code>+softwareComposition 1</code>) durch <code>Composition::CompositionType</code> (<code>ComponentType</code>, Stereotyp «atpType»).\n</li><li><code>Services::ServiceComponentPrototype</code> (<code>Identifiable</code>, Stereotyp «atpPrototype»): Typisiert über die Assoziation «isOfType» (unbenanntes Ende zu <code>+serviceComponent 1</code>) durch <code>Components::ServiceComponentType</code> (<code>AtomicSoftwareComponentType</code>).\n</li><li><code>Composition::ServiceConnectorPrototype</code> (<code>ConnectorPrototype</code>, Stereotyp «atpStructureElement»): Repräsentiert die Verbindungsbeziehungen innerhalb der ECU-Software-Komposition.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Beziehungen definieren die strukturelle Instanziierungshierarchie beim Erstellen eines ECU-Extracts: Ausgehend von der Gesamtsystemkonfiguration werden die Software-Architektur (<code>SoftwareComposition</code>) und die ECU-spezifischen Service-Instanzen (<code>ServiceComponentPrototype</code>, <code>ServiceConnectorPrototype</code>) an die <code>EcuSwComposition</code> gebunden und ihren konkreten Komponententypen zugeordnet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Modellierungsregeln für AUTOSAR-Autoren und Werkzeughersteller:</p>\n<ul class=\"fig-list\"><li>Eine <code>EcuConfiguration</code> muss exakt einen Verweis auf das übergeordnete <code>SystemTemplate::System</code> sowie exakt eine <code>EcuSwComposition</code> bereitstellen.\n</li><li>Jede <code>EcuSwComposition</code> muss eindeutig auf das zugehörige <code>SystemTemplate::System</code> (<code>+ecuExtract 1</code>) verweisen.\n</li><li>Die Typisierungsbeziehungen über <code>«isOfType»</code> verlangen zwingend, dass <code>SoftwareComposition</code> auf einen <code>CompositionType</code> und <code>ServiceComponentPrototype</code> auf einen <code>ServiceComponentType</code> referenziert (jeweils Zielmultiplizität <code>1</code>).\n</li><li>Mehrere Service-Komponenten und Service-Konnektoren können modular innerhalb einer <code>EcuSwComposition</code> kombiniert werden (<code>0..*</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-066e79bd598ddf56", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR-Software-Component-Templates. Das Diagramm spezifiziert die Einbettung der ECU-Software-Komposition (<code>EcuSwComposition</code>) im Kontext der System- und ECU-Konfiguration (<code>EcuConfiguration</code>, <code>SystemTemplate::System</code>) sowie die Zuordnung von Service-Komponenten und Service-Konnektoren innerhalb eines Steuergeräte-Auszugs (ECU Extract).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell umfasst folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>EcuConfiguration</code> (<code>ARElement</code>): Referenziert über <code>+ecuExtract</code> genau ein <code>SystemTemplate::System</code> (Kardinalität <code>1</code>) und über <code>+ecuSwComposition</code> genau eine <code>Services::EcuSwComposition</code> (Kardinalität <code>1</code>).\n</li><li><code>SystemTemplate::System</code> (<code>ARElement</code>, Stereotyp «atpStructureElement»): Besitzt die Attribute <code>ecuExtractVersion: String [0..1]</code> und <code>systemVersion: String</code>. Es enthält per Komposition über die Rolle <code>+softwareComposition</code> genau ein <code>SystemTemplate::SoftwareComposition</code> (Kardinalität <code>1</code>).\n</li><li><code>Services::EcuSwComposition</code> (<code>ARElement</code>, Stereotyp «atpStructureElement»): Referenziert über <code>+ecuExtract</code> gerichtet genau ein <code>SystemTemplate::System</code> (Kardinalität <code>1</code>). Sie aggregiert per Komposition über <code>+component</code> beliebig viele Instanzen von <code>Services::ServiceComponentPrototype</code> (Kardinalität <code>*</code>) sowie über <code>+connector</code> beliebig viele Instanzen von <code>Composition::ServiceConnectorPrototype</code> (Kardinalität <code>*</code>).\n</li><li><code>SystemTemplate::SoftwareComposition</code> (<code>Identifiable</code>, Stereotyp «atpPrototype»): Typisiert über die Assoziation «isOfType» (<code>*</code> zu <code>+softwareComposition 1</code>) durch <code>Composition::CompositionType</code> (<code>ComponentType</code>, Stereotyp «atpType»).\n</li><li><code>Services::ServiceComponentPrototype</code> (<code>Identifiable</code>, Stereotyp «atpPrototype»): Typisiert über die Assoziation «isOfType» (unbenanntes Ende zu <code>+serviceComponent 1</code>) durch <code>Components::ServiceComponentType</code> (<code>AtomicSoftwareComponentType</code>, Stereotyp «atpType»).\n</li><li><code>Composition::ServiceConnectorPrototype</code> (<code>ConnectorPrototype</code>, Stereotyp «atpStructureElement»): Repräsentiert die Verbindungsbeziehungen innerhalb der ECU-Software-Komposition.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Beziehungen definieren die strukturelle Instanziierungshierarchie beim Erstellen eines ECU-Extracts: Ausgehend von der Gesamtsystemkonfiguration werden die Software-Architektur (<code>SoftwareComposition</code>) und die ECU-spezifischen Service-Instanzen (<code>ServiceComponentPrototype</code>, <code>ServiceConnectorPrototype</code>) an die <code>EcuSwComposition</code> gebunden und ihren konkreten Komponententypen zugeordnet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Modellierungsregeln für AUTOSAR-Autoren und Werkzeughersteller:</p>\n<ul class=\"fig-list\"><li>Eine <code>EcuConfiguration</code> muss exakt einen Verweis auf das übergeordnete <code>SystemTemplate::System</code> sowie exakt eine <code>EcuSwComposition</code> bereitstellen.\n</li><li>Jede <code>EcuSwComposition</code> muss eindeutig auf das zugehörige <code>SystemTemplate::System</code> (<code>+ecuExtract 1</code>) verweisen.\n</li><li><code>SystemTemplate::System</code> erfordert die Angabe einer <code>systemVersion</code> (String, Kardinalität <code>1</code>) und erlaubt optional eine <code>ecuExtractVersion</code> (String, Kardinalität <code>0..1</code>).\n</li><li>Die Typisierungsbeziehungen über <code>«isOfType»</code> verlangen zwingend, dass <code>SoftwareComposition</code> auf einen <code>CompositionType</code> und <code>ServiceComponentPrototype</code> auf einen <code>ServiceComponentType</code> referenziert (jeweils Zielmultiplizität <code>1</code>).\n</li><li>Mehrere Service-Komponenten und Service-Konnektoren können modular innerhalb einer <code>EcuSwComposition</code> kombiniert werden (<code>0..*</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c372ae70c5705b3c", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR-Software-Component-Templates. Das Diagramm spezifiziert die Einbettung der ECU-Software-Komposition (<code>EcuSwComposition</code>) im Kontext der System- und ECU-Konfiguration (<code>EcuConfiguration</code>, <code>SystemTemplate::System</code>) sowie die Zuordnung von Service-Komponenten und Service-Konnektoren innerhalb eines Steuergeräte-Auszugs (ECU Extract).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell umfasst folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>EcuConfiguration</code> (<code>ARElement</code>): Referenziert über <code>+ecuExtract</code> genau ein <code>SystemTemplate::System</code> (Kardinalität <code>1</code>) und über <code>+ecuSwComposition</code> genau eine <code>Services::EcuSwComposition</code> (Kardinalität <code>1</code>).\n</li><li><code>SystemTemplate::System</code> (<code>ARElement</code>, Stereotyp «atpStructureElement»): Besitzt die Attribute <code>ecuExtractVersion: String [0..1]</code> und <code>systemVersion: String</code>. Es enthält per Komposition über die Rolle <code>+softwareComposition</code> genau ein <code>SystemTemplate::SoftwareComposition</code> (Kardinalität <code>1</code>).\n</li><li><code>Services::EcuSwComposition</code> (<code>ARElement</code>, Stereotyp «atpStructureElement»): Referenziert über <code>+ecuExtract</code> gerichtet genau ein <code>SystemTemplate::System</code> (Kardinalität <code>1</code>). Sie aggregiert per Komposition über <code>+component</code> beliebig viele Instanzen von <code>Services::ServiceComponentPrototype</code> (Kardinalität <code>*</code>) sowie über <code>+connector</code> beliebig viele Instanzen von <code>Composition::ServiceConnectorPrototype</code> (Kardinalität <code>*</code>).\n</li><li><code>SystemTemplate::SoftwareComposition</code> (<code>Identifiable</code>, Stereotyp «atpPrototype»): Typisiert über die Assoziation «isOfType» (<code>*</code> zu <code>+softwareComposition 1</code>) durch <code>Composition::CompositionType</code> (<code>ComponentType</code>, Stereotyp «atpType»).\n</li><li><code>Services::ServiceComponentPrototype</code> (<code>Identifiable</code>, Stereotyp «atpPrototype»): Typisiert über die Assoziation «isOfType» (unbenanntes Ende zu <code>+serviceComponent 1</code>) durch <code>Components::ServiceComponentType</code> (<code>AtomicSoftwareComponentType</code>, Stereotyp «atpType»).\n</li><li><code>Composition::ServiceConnectorPrototype</code> (<code>ConnectorPrototype</code>, Stereotyp «atpStructureElement»): Repräsentiert die Verbindungsbeziehungen innerhalb der ECU-Software-Komposition.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Beziehungen definieren die strukturelle Instanziierungshierarchie beim Erstellen eines ECU-Extracts: Ausgehend von der Gesamtsystemkonfiguration werden die Software-Architektur (<code>SoftwareComposition</code>) und die ECU-spezifischen Service-Instanzen (<code>ServiceComponentPrototype</code>, <code>ServiceConnectorPrototype</code>) an die <code>EcuSwComposition</code> gebunden und ihren konkreten Komponententypen zugeordnet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Modellierungsregeln für AUTOSAR-Autoren und Werkzeughersteller:</p>\n<ul class=\"fig-list\"><li>Eine <code>EcuConfiguration</code> muss exakt einen Verweis auf das übergeordnete <code>SystemTemplate::System</code> sowie exakt eine <code>EcuSwComposition</code> bereitstellen.\n</li><li>Jede <code>EcuSwComposition</code> muss eindeutig auf das zugehörige <code>SystemTemplate::System</code> (<code>+ecuExtract 1</code>) verweisen.\n</li><li><code>SystemTemplate::System</code> erfordert die Angabe einer <code>systemVersion</code> (String, Kardinalität <code>1</code>) und erlaubt optional eine <code>ecuExtractVersion</code> (String, Kardinalität <code>0..1</code>).\n</li><li>Die Typisierungsbeziehungen über <code>«isOfType»</code> verlangen zwingend, dass <code>SoftwareComposition</code> auf einen <code>CompositionType</code> und <code>ServiceComponentPrototype</code> auf einen <code>ServiceComponentType</code> referenziert (jeweils Zielmultiplizität <code>1</code>).\n</li><li>Mehrere Service-Komponenten und Service-Konnektoren können modular innerhalb einer <code>EcuSwComposition</code> kombiniert werden (<code>0..*</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-80d126a38f643b24", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur des AUTOSAR-Software-Component-Templates. Das Diagramm spezifiziert die Einbettung der ECU-Software-Komposition (<code>EcuSwComposition</code>) im Kontext der System- und ECU-Konfiguration (<code>EcuConfiguration</code>, <code>SystemTemplate::System</code>) sowie die Zuordnung von Service-Komponenten und Service-Konnektoren innerhalb eines Steuergeräte-Auszugs (ECU Extract).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell umfasst folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>EcuConfiguration</code> (<code>ARElement</code>): Referenziert über <code>+ecuExtract</code> genau ein <code>SystemTemplate::System</code> (Kardinalität <code>1</code>) und über <code>+ecuSwComposition</code> genau eine <code>Services::EcuSwComposition</code> (Kardinalität <code>1</code>).\n</li><li><code>SystemTemplate::System</code> (<code>ARElement</code>, Stereotyp «atpStructureElement»): Besitzt die Attribute <code>ecuExtractVersion :String [0..1]</code>, <code>pncVectorLength :Integer [0..1]</code>, <code>pncVectorOffset :Integer [0..1]</code> und <code>systemVersion :String</code>. Es enthält per Komposition über die Rolle <code>+softwareComposition</code> optional eine <code>SystemTemplate::SoftwareComposition</code> (Kardinalität <code>0..1</code>).\n</li><li><code>Services::EcuSwComposition</code> (<code>ARElement</code>, Stereotyp «atpStructureElement»): Referenziert über <code>+ecuExtract</code> gerichtet genau ein <code>SystemTemplate::System</code> (Kardinalität <code>1</code>). Sie aggregiert per Komposition über <code>+component</code> beliebig viele Instanzen von <code>Services::ServiceComponentPrototype</code> (Kardinalität <code>*</code>) sowie über <code>+connector</code> beliebig viele Instanzen von <code>Composition::ServiceConnectorPrototype</code> (Kardinalität <code>*</code>).\n</li><li><code>SystemTemplate::SoftwareComposition</code> (<code>Identifiable</code>, Stereotyp «atpPrototype»): Typisiert über die Assoziation «isOfType» (<code>*</code> zu <code>+softwareComposition 1</code>) durch <code>Composition::CompositionType</code> (<code>ComponentType</code>, Stereotyp «atpType»).\n</li><li><code>Services::ServiceComponentPrototype</code> (<code>Identifiable</code>, Stereotyp «atpPrototype»): Typisiert über die Assoziation «isOfType» (unbenanntes Ende zu <code>+serviceComponent 1</code>) durch <code>Components::ServiceComponentType</code> (<code>AtomicSoftwareComponentType</code>, Stereotyp «atpType»).\n</li><li><code>Composition::ServiceConnectorPrototype</code> (<code>ConnectorPrototype</code>, Stereotyp «atpStructureElement»): Repräsentiert die Verbindungsbeziehungen innerhalb der ECU-Software-Komposition.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Beziehungen definieren die strukturelle Instanziierungshierarchie beim Erstellen eines ECU-Extracts: Ausgehend von der Gesamtsystemkonfiguration werden die Software-Architektur (<code>SoftwareComposition</code>) und die ECU-spezifischen Service-Instanzen (<code>ServiceComponentPrototype</code>, <code>ServiceConnectorPrototype</code>) an die <code>EcuSwComposition</code> gebunden und ihren konkreten Komponententypen zugeordnet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Modellierungsregeln für AUTOSAR-Autoren und Werkzeughersteller:</p>\n<ul class=\"fig-list\"><li>Eine <code>EcuConfiguration</code> muss exakt einen Verweis auf das übergeordnete <code>SystemTemplate::System</code> sowie exakt eine <code>EcuSwComposition</code> bereitstellen.\n</li><li>Jede <code>EcuSwComposition</code> muss eindeutig auf das zugehörige <code>SystemTemplate::System</code> (<code>+ecuExtract 1</code>) verweisen.\n</li><li><code>SystemTemplate::System</code> erfordert die Angabe einer <code>systemVersion :String</code> (Kardinalität <code>1</code>) und erlaubt optional <code>ecuExtractVersion :String [0..1]</code>, <code>pncVectorLength :Integer [0..1]</code> sowie <code>pncVectorOffset :Integer [0..1]</code> für Partial-Network-Cluster-Konfigurationen.\n</li><li>Die Komposition <code>+softwareComposition</code> unterhalb von <code>SystemTemplate::System</code> ist optional (Kardinalität <code>0..1</code>).\n</li><li>Die Typisierungsbeziehungen über <code>«isOfType»</code> verlangen zwingend, dass <code>SoftwareComposition</code> auf einen <code>CompositionType</code> und <code>ServiceComponentPrototype</code> auf einen <code>ServiceComponentType</code> referenziert (jeweils Zielmultiplizität <code>1</code>).\n</li><li>Mehrere Service-Komponenten und Service-Konnektoren können modular innerhalb einer <code>EcuSwComposition</code> kombiniert werden (<code>0..*</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9eecb896f4ebe28c", "to": "FIG-066e79bd598ddf56", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>SystemTemplate::System</code>: Attribute <code>ecuExtractVersion: String [0..1]</code> und <code>systemVersion: String</code> ergänzt (rot markiert).\n</li><li><code>Composition::CompositionType</code>: Stereotyp «atpType» explizit deklariert.\n</li><li><code>Components::ServiceComponentType</code>: Stereotyp «atpType» ergänzt.\n</li><li><code>Services::EcuSwComposition</code>: Textformatierung von Stereotyp und Bezeichner zusammengezogen.\n</li></ul>"}, {"from": "FIG-066e79bd598ddf56", "to": "FIG-c372ae70c5705b3c", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c372ae70c5705b3c", "to": "FIG-80d126a38f643b24", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>SystemTemplate::System</code>: Attribute <code>pncVectorLength: Integer [0..1]</code> und <code>pncVectorOffset: Integer [0..1]</code> ergänzt (rot markiert).\n</li><li><code>SystemTemplate::System</code> zu <code>SystemTemplate::SoftwareComposition</code>: Multiplizität der Kompositionsrolle <code>+softwareComposition</code> von <code>1</code> auf <code>0..1</code> geändert.\n</li></ul>"}]};
